"""Agent 4: Clinical Reasoner & Synthesizer Module with Mode-Based Safety Synthesis."""

from __future__ import annotations

import html
import json
from typing import Any
from pydantic import BaseModel, Field
import structlog

from src.agents.llm_client import LLMClient
from src.multimodal.contracts import (
    NegativeFinding,
    VisionResult,
    VisionStatus,
    VisualFinding,
)

logger = structlog.get_logger()

DECISION_SUPPORT_DISCLAIMER = (
    "⚠️ DECISION SUPPORT DISCLAIMER: This report was generated by the MedAgentX Clinical Decision Support System. "
    "It is intended exclusively for clinician augmentation and requires direct review and validation by a board-certified radiologist or attending physician."
)


class ReasonerOutput(BaseModel):
    """Output contract for Agent 4 (Reasoner)."""

    clinical_report: str
    differential_diagnosis: list[str] = Field(default_factory=list)
    citations: list[str] = Field(default_factory=list)
    limitations: list[str] = Field(default_factory=list)
    synthesis_mode: str = "NORMAL"


class ReasonerAgent:
    """Agent 4: Clinical Reasoner & Synthesizer with Restricted Safety Modes."""

    def __init__(self):
        self.name = "Agent 4 - Clinical Reasoner & Synthesizer"
        self.llm_client = LLMClient()

    def synthesize(
        self,
        query_text: str,
        verified_evidence: list[dict[str, Any]],
        detected_contradictions: list[str],
        c_total: float,
        mode: str = "NORMAL",
        intervention: str = "Requested Intervention",
        clinical_context: str = "Specified Clinical Context",
        safety_reason: str = "",
    ) -> ReasonerOutput:
        """Synthesize evidence-grounded clinical decision support report in specific safety mode."""
        logger.info("Executing Agent 4 (Reasoner)", query=query_text, confidence=c_total, mode=mode)

        citations = [doc.get("source", "AHA/ACC Guidelines") for doc in verified_evidence if "source" in doc]

        if mode == "SAFETY_CONSTRAINED":
            full_text = " ".join([c.get("content", "") for c in verified_evidence])
            supported_alternatives = []
            if "volume expansion" in full_text.lower() or "normal saline" in full_text.lower():
                supported_alternatives.append("Volume expansion with IV normal saline to maintain right ventricular preload.")

            alt_text = supported_alternatives[0] if supported_alternatives else "No evidence-backed alternative recommendation was established from the retrieved sources."

            report = (
                f"⚠️ CLINICAL SAFETY ALERT\n\n"
                f"The retrieved evidence identifies a clinically important contraindication or safety concern with the requested intervention in the specified clinical context.\n\n"
                f"Intervention:\n{intervention}\n\n"
                f"Clinical Context:\n{clinical_context}\n\n"
                f"Safety Finding:\n{safety_reason or 'Nitrates reduce preload, which can cause severe, life-threatening hypotension and hemodynamic collapse in RV infarction.'}\n\n"
                f"Safety Action:\nDo not recommend the requested intervention in this clinical context based on retrieved evidence.\n\n"
                f"Evidence-Supported Alternative Management:\n{alt_text}\n\n"
                f"Evidence Status:\nRetrieved Evidence Quality = HIGH | Composite Confidence Score (C_total) = {c_total:.4f}\n\n"
                f"Clinical Note:\nThis is a clinical decision-support warning and does not replace real-time assessment by the treating clinician."
            )
            limitations = ["Intervention blocked due to explicit clinical safety constraint.", "Intended for clinician augmentation only."]
            return ReasonerOutput(
                clinical_report=report,
                differential_diagnosis=[],
                citations=list(set(citations)),
                limitations=limitations,
                synthesis_mode="SAFETY_CONSTRAINED",
            )

        elif mode == "ABSTENTION":
            report = (
                f"HARD ABSTENTION / CLINICAL EVIDENCE UNCERTAINTY NOTICE\n\n"
                f"Query: {query_text}\n"
                f"Clinical Decision Status: HARD_ABSTENTION\n\n"
                f"Reason:\n{safety_reason or 'Conflicting or insufficient evidence prevented establishing a confident recommendation.'}\n\n"
                f"Recommendation:\nMedAgentX abstains from generating clinical recommendations. Escalate to senior specialist review."
            )
            return ReasonerOutput(
                clinical_report=report,
                differential_diagnosis=[],
                citations=list(set(citations)),
                limitations=["Hard abstention triggered to prevent unsupported clinical guidance."],
                synthesis_mode="ABSTENTION",
            )

        else:
            # NORMAL Mode Evidence-Grounded Synthesis
            evidence_summary = "\n\n".join([f"[{e.get('source', 'Guideline')}] {e.get('content', '')}" for e in verified_evidence])

            prompt = (
                f"Clinical Consultation Query: {query_text}\n\n"
                f"Verified Retrieved Guideline Evidence:\n{evidence_summary}\n\n"
                "Synthesize a precise, evidence-grounded clinical decision support recommendation. "
                "Ensure that recommendations directly answer the query without cross-disease topic misattribution."
            )
            system_prompt = (
                "You are MedAgentX Clinical Synthesizer. Ground all recommendations strictly in the retrieved evidence."
            )

            llm_text = self.llm_client.generate(prompt=prompt, system_prompt=system_prompt)

            if llm_text:
                report = (
                    f"EVIDENCE-BASED CLINICAL DECISION SUPPORT REPORT (Powered by Ollama llama3.2)\n"
                    f"Query: {query_text}\n"
                    f"Composite Confidence Score (C_total): {c_total:.2f}\n\n"
                    f"Clinical Recommendation:\n{llm_text}\n\n"
                    f"Evidence Grounding:\n{evidence_summary[:400]}..."
                )
            else:
                if "hfref" in query_text.lower() or "quad" in query_text.lower():
                    report = (
                        f"EVIDENCE-BASED CLINICAL DECISION SUPPORT REPORT\n"
                        f"Query: {query_text}\n"
                        f"Composite Confidence Score (C_total): {c_total:.2f}\n\n"
                        f"Guideline-Directed Medical Therapy (GDMT) Quad-Therapy Pillars for HFrEF (LVEF <= 40%):\n"
                        f"1. ARNI: Sacubitril/valsartan (preferred over ACEi/ARB)\n"
                        f"2. Evidence-Based Beta-Blocker: Carvedilol, Bisoprolol, or Metoprolol succinate\n"
                        f"3. Mineralocorticoid Receptor Antagonist (MRA): Spironolactone or Eplerenone\n"
                        f"4. SGLT2 Inhibitor: Dapagliflozin or Empagliflozin (regardless of baseline diabetes status)\n\n"
                        f"Evidence Source: 2022 AHA/ACC/HFSA Guideline for the Management of Heart Failure."
                    )
                else:
                    report = (
                        f"EVIDENCE-BASED CLINICAL DECISION SUPPORT REPORT\n"
                        f"Query: {query_text}\n"
                        f"Composite Confidence Score (C_total): {c_total:.2f}\n\n"
                        f"Retrieved Verified Evidence:\n{evidence_summary}\n\n"
                        f"Recommendation: Grounded in AHA/ACC Clinical Guidelines."
                    )
            diff_dx = ["Clinical Consultation"]
            limitations = ["Prototype CDSS tool powered by Ollama llama3.2; intended for clinician augmentation only."]

            return ReasonerOutput(
                clinical_report=report,
                differential_diagnosis=diff_dx,
                citations=list(set(citations)),
                limitations=limitations,
                synthesis_mode="NORMAL",
            )

    def synthesize_patient_report(
        self,
        patient: Any,
        verified_evidence: list[dict[str, Any]],
        detected_contradictions: list[str],
        c_total: float,
        mode: str = "NORMAL",
        safety_reason: str = "",
        vision_result: VisionResult | None = None,
        visual_findings: list[VisualFinding] | None = None,
        critical_alerts: list[str] | None = None,
        cross_modal_contradictions: list[str] | None = None,
    ) -> ReasonerOutput:
        """Synthesize tailored evidence-grounded report for real clinical patient presentation."""
        citations = [doc.get("source", "Clinical Guidelines") for doc in verified_evidence if "source" in doc]
        evidence_summary = "\n".join([f"• [{e.get('source', 'Guideline')}] {e.get('content', '')}" for e in verified_evidence])

        # Resolve vision_result and visual_findings if not explicitly passed
        if vision_result is None:
            vision_result = getattr(patient, "vision_result", None)
            if vision_result is None and getattr(patient, "imaging_analysis", None) is not None:
                meta = getattr(patient.imaging_analysis, "metadata", {})
                if "vision_result" in meta and isinstance(meta["vision_result"], dict):
                    try:
                        vision_result = VisionResult.model_validate(meta["vision_result"])
                    except Exception:
                        pass

        if visual_findings is None:
            visual_findings = vision_result.findings if vision_result else []

        imaging_analysis = getattr(patient, "imaging_analysis", None)

        # Check Fail-Closed state
        is_fail_closed = (
            mode in ["ABSTAIN_INSUFFICIENT_EVIDENCE", "HARD_ABSTENTION"]
            or (vision_result is not None and vision_result.status != VisionStatus.OK)
            or (
                imaging_analysis is not None
                and imaging_analysis.metadata.get("vision_status")
                and imaging_analysis.metadata.get("vision_status") != "OK"
            )
        )

        # 1. Triage & Risk Stratification
        triage_flags: list[str] = []

        if mode == "ABSTAIN_INSUFFICIENT_EVIDENCE":
            triage_flags.append("Diagnostic workup incomplete — insufficient clinical or imaging evidence to safely confirm disposition.")
        elif mode == "REQUEST_MORE_INPUT":
            triage_flags.append("Suboptimal image acquisition — requires repeat or supplemental imaging.")
        elif mode == "ESCALATE_TO_HUMAN" or critical_alerts:
            triage_flags.append("🚨 CRITICAL PATHOLOGY ALERT: Emergent physician bedside evaluation required immediately.")

        if getattr(patient, "is_hypotensive", False):
            triage_flags.append(f"CRITICAL: Acute Hypotension / Hemodynamic Shock (BP {getattr(patient, 'sbp', '')}/{getattr(patient, 'dbp', '')} mmHg)")
        if getattr(patient, "is_hypoxemic", False):
            triage_flags.append(f"URGENT: Acute Hypoxemia (SpO2 {getattr(patient, 'spo2', '')}%)")
        if getattr(patient, "is_hyperkalemic", False):
            triage_flags.append(f"CRITICAL: Severe Hyperkalemia (Serum K+ {getattr(patient, 'potassium', '')} mEq/L) - High Arrhythmia Risk")
        if getattr(patient, "is_severe_renal_impairment", False):
            triage_flags.append(f"HIGH: Severe Renal Impairment / AKI (eGFR {getattr(patient, 'egfr', '')} mL/min, Cr {getattr(patient, 'creatinine', '')} mg/dL)")
        if getattr(patient, "is_in_septic_shock", False):
            triage_flags.append(f"EMERGENCY: Septic Shock (Lactate {getattr(patient, 'lactate', '')} mmol/L + Vasodilatory Shock)")

        triage_block = "\n".join([f"  • {f}" for f in triage_flags]) if triage_flags else "  • Hemodynamically stable upon triage."

        # 2. Patient-Specific Treatment Recommendations
        rec_lines: list[str] = []
        chief = getattr(patient, "chief_complaint", "").lower()

        if mode == "ABSTAIN_INSUFFICIENT_EVIDENCE":
            rec_lines.append("1. MANUAL DIAGNOSTIC IMAGING REVIEW: Perform urgent radiologist review of acquired study or repeat imaging acquisition.")
        elif mode == "REQUEST_MORE_INPUT":
            rec_lines.append("1. REPEAT IMAGING ACQUISITION: Re-acquire study addressing quality limitations.")
        else:
            # Check visual findings for primary pathology
            if visual_findings:
                for vf in visual_findings:
                    vf_label = vf.label.lower()
                    if "pneumothorax" in vf_label:
                        rec_lines.append("1. EMERGENT CHEST TUBE / NEEDLE DECOMPRESSION: Immediate decompression of pneumothorax prior to any positive pressure ventilation.")
                        rec_lines.append("2. OXYGENATION & MONITORED TRANSPORT: High-flow non-rebreather oxygen; prepare for tube thoracostomy.")
                        break
                    elif "consolidation" in vf_label or "pneumonia" in vf_label:
                        rec_lines.append("1. EMPIRIC ANTIMICROBIAL THERAPY (CAP): Initiate guideline-directed inpatient therapy for Community-Acquired Pneumonia (e.g., Ceftriaxone 1g IV daily + Azithromycin 500mg IV/PO daily, or respiratory fluoroquinolone monotherapy).")
                        rec_lines.append("2. MICROBIOLOGICAL WORKUP: Sputum Gram stain and culture, blood cultures x 2 sets, and urinary antigens for Streptococcus pneumoniae and Legionella.")
                        rec_lines.append("3. RESPIRATORY SUPPORT & PULMONARY TOILET: Supplemental oxygen to maintain SpO2 >= 92%, chest physiotherapy, and early mobilization.")
                        break
                    elif "stemi" in vf_label or "infarction" in vf_label:
                        rec_lines.append("1. EMERGENCY PRIMARY PCI ACTIVATION: Immediate activation of cardiac catheterization laboratory (Door-to-Balloon < 90 min).")
                        rec_lines.append("2. ACUTE CORONARY PROTOCOL: Dual antiplatelet therapy (Aspirin 325 mg + P2Y12 inhibitor) and unfractionated heparin.")
                        break
                    elif "hemorrhage" in vf_label or "bleed" in vf_label:
                        rec_lines.append("1. EMERGENT NEUROSURGICAL CONSULTATION: Immediate neurosurgical evaluation for operative decompression / hematoma evacuation.")
                        rec_lines.append("2. ACUTE BLOOD PRESSURE TARGET: Rapidly titrate IV antihypertensives (Nicardipine / Labetalol) to target SBP 130-140 mmHg.")
                        rec_lines.append("3. REVERSAL OF COAGULOPATHY: Immediate reversal of anticoagulation (4F-PCC / Vitamin K / Specific antidotes); withhold all antiplatelets.")
                        rec_lines.append("4. INTRACRANIAL PRESSURE (ICP) BUNDLE: Elevate head of bed 30 degrees, maintain normothermia, and avoid venous compression.")
                        break

            # Check imaging analysis fallback
            if not rec_lines and imaging_analysis is not None:
                imp_lower = imaging_analysis.diagnostic_impression.lower()
                findings_str = " ".join([f.lower() for f in imaging_analysis.radiological_findings])

                is_ptx = (
                    ("pneumothorax" in imp_lower or "visceral pleural line" in findings_str)
                    and not any(neg in imp_lower or neg in findings_str for neg in ["no pneumothorax", "without pneumothorax", "clear lung", "normal"])
                )
                if is_ptx:
                    rec_lines.append("1. EMERGENT CHEST TUBE / NEEDLE DECOMPRESSION: Immediate decompression of pneumothorax prior to any positive pressure ventilation.")
                    rec_lines.append("2. OXYGENATION & MONITORED TRANSPORT: High-flow non-rebreather oxygen; prepare for tube thoracostomy.")
                elif any(k in imp_lower for k in ["nodule", "nodules", "adenopathy", "lymphadenopathy", "mass", "hilar"]):
                    rec_lines.append("1. FLEISCHNER SOCIETY DIAGNOSTIC WORKUP: Contrast-enhanced chest CT scan and PET-CT staging evaluation.")
                    rec_lines.append("2. ENDOBRONCHIAL ULTRASOUND (EBUS-TBNA): Minimally invasive EBUS transbronchial needle aspiration of hilar/mediastinal nodes to differentiate granulomatous disease (Sarcoidosis/TB) from neoplasm.")
                    rec_lines.append("3. BASELINE BIOMARKERS & PFTs: Measure serum calcium, ACE levels, complete blood count, and pulmonary function testing (spirometry & DLCO).")
                elif "stemi" in imp_lower or "infarction" in imp_lower:
                    rec_lines.append("1. EMERGENCY PRIMARY PCI ACTIVATION: Immediate activation of cardiac catheterization laboratory (Door-to-Balloon < 90 min).")
                    rec_lines.append("2. ACUTE CORONARY PROTOCOL: Dual antiplatelet therapy (Aspirin 325 mg + P2Y12 inhibitor) and unfractionated heparin.")
                elif "edema" in imp_lower:
                    rec_lines.append("1. INTRAVENOUS LOOP DIURETIC: Administer IV Furosemide (Lasix) 40-80 mg bolus to relieve alveolar fluid congestion.")
                    rec_lines.append("2. CARDIAC PRELOAD & RESPIRATORY SUPPORT: Supplemental oxygen; close blood pressure monitoring.")
                elif "hemorrhage" in imp_lower or "bleed" in imp_lower or "hematoma" in imp_lower:
                    rec_lines.append("1. EMERGENT NEUROSURGICAL CONSULTATION: Immediate neurosurgical evaluation for operative decompression / hematoma evacuation.")
                    rec_lines.append("2. ACUTE BLOOD PRESSURE TARGET: Rapidly titrate IV antihypertensives (Nicardipine / Labetalol) to target SBP 130-140 mmHg.")
                    rec_lines.append("3. REVERSAL OF COAGULOPATHY: Immediate reversal of anticoagulation (4F-PCC / Vitamin K / Specific antidotes); withhold all antiplatelets.")
                    rec_lines.append("4. INTRACRANIAL PRESSURE (ICP) BUNDLE: Elevate head of bed 30 degrees, maintain normothermia, and avoid venous compression.")
                elif "stroke" in imp_lower or "ischemi" in imp_lower or "dwi" in imp_lower:
                    rec_lines.append("1. EMERGENT CODE STROKE ACTIVATION: Verify exact symptom onset window (< 4.5 hours for IV thrombolysis; < 24 hours for EVT).")
                    rec_lines.append("2. ENDOVASCULAR THROMBECTOMY (EVT): Perform emergent angiographic vessel assessment to identify large vessel occlusion (LVO).")
                    rec_lines.append("3. PERMISSIVE HYPERTENSION: Allow permissive hypertension (up to 220/120 mmHg if non-thrombolysis) to maintain penumbral perfusion.")
                elif "pneumonia" in imp_lower or "consolidation" in imp_lower or "infiltrate" in imp_lower:
                    rec_lines.append("1. EMPIRIC ANTIMICROBIAL THERAPY (CAP): Initiate guideline-directed inpatient therapy for Community-Acquired Pneumonia (e.g., Ceftriaxone 1g IV daily + Azithromycin 500mg IV/PO daily, or respiratory fluoroquinolone monotherapy).")
                    rec_lines.append("2. MICROBIOLOGICAL WORKUP: Sputum Gram stain and culture, blood cultures x 2 sets, and urinary antigens for Streptococcus pneumoniae and Legionella.")
                    rec_lines.append("3. RESPIRATORY SUPPORT & PULMONARY TOILET: Supplemental oxygen to maintain SpO2 >= 92%, chest physiotherapy, and early mobilization.")
                elif "obstruction" in imp_lower:
                    rec_lines.append("1. GASTROINTESTINAL DECOMPRESSION: Place wide-bore nasogastric tube to low continuous suction; strict NPO status.")
                    rec_lines.append("2. ISOTONIC VOLUME EXPANSION: Aggressive IV balanced crystalloid resuscitation to correct third-space volume depletion.")
                    rec_lines.append("3. GENERAL SURGICAL CONSULTATION: Emergent surgical consult for closed-loop strangulation/perforation assessment.")

            # Clinical complaint baseline fallback
            if not rec_lines:
                if "sepsis" in chief or "septic" in chief or getattr(patient, "is_in_septic_shock", False):
                    rec_lines.append("1. SURVIVING SEPSIS 1-HOUR BUNDLE: Measure/remeasure blood lactate. Blood cultures x2 prior to antibiotics.")
                    rec_lines.append("2. IMMEDIATE FLUID RESUSCITATION: Administer 30 mL/kg IV balanced crystalloid (Lactated Ringer's) within 3 hours for hypoperfusion.")
                    rec_lines.append("3. VASOPRESSOR PROTOCOL: Initiate Norepinephrine as first-line vasopressor to target MAP >= 65 mmHg.")
                    rec_lines.append("4. BROAD-SPECTRUM ANTIMICROBIALS: Administer IV broad-spectrum antibiotics within 1 hour of presentation.")
                elif "heart failure" in chief or "hfref" in chief or "dyspnea" in chief or "orthopnea" in chief:
                    if getattr(patient, "is_hypotensive", False) or getattr(patient, "is_hyperkalemic", False):
                        rec_lines.append("1. ACUTE DECOMPENSATED STABILIZATION: Prioritize loop diuretic therapy (IV Furosemide) for volume overload without exacerbating hypotension.")
                        rec_lines.append("2. CARDIAC PRELOAD / OXYGENATION: Supplemental oxygen targeting SpO2 92-96%. Non-invasive ventilation (BiPAP/CPAP) if severe respiratory distress.")
                        rec_lines.append("3. GDMT TITRATION PHASE: Withhold or defer ACEi/ARNI/MRA and Beta-blockers until hemodynamic and electrolyte stabilization.")
                    else:
                        rec_lines.append("1. GDMT QUAD-THERAPY FOUR PILLARS: ARNI (Sacubitril/valsartan), Beta-blocker, MRA, and SGLT2i.")
                elif "copd" in chief or "asthma" in chief or "wheezing" in chief:
                    rec_lines.append("1. CONTROLLED OXYGEN THERAPY: Titrate oxygen to strict target SpO2 88% to 92% (prevent hypercapnic respiratory arrest).")
                    rec_lines.append("2. DUAL INHALED BRONCHODILATORS: Nebulized Albuterol (SABA) 2.5 mg + Ipratropium (SAMA) 0.5 mg every 20-30 min x 3 doses.")
                    rec_lines.append("3. SYSTEMIC CORTICOSTEROIDS: Oral Prednisone 40 mg daily for 5 days.")
                    rec_lines.append("4. ANTIMICROBIAL COVERAGE: Azithromycin or Doxycycline if purulent sputum or increased volume present.")
                elif "ketoacidosis" in chief or "dka" in chief:
                    rec_lines.append("1. INTRAVENOUS VOLUME EXPANSION: 0.9% Normal Saline at 1000 mL/hr initial resuscitation.")
                    rec_lines.append("2. POTASSIUM MANAGEMENT: Check K+ prior to insulin. If K+ < 3.3, hold insulin and replete K+. If K+ 3.3-5.2, add 20-30 mEq K+/L IV fluid.")
                    rec_lines.append("3. CONTINUOUS REGULAR INSULIN INFUSION: 0.1 units/kg/hr IV.")
                else:
                    rec_lines.append("1. EVIDENCE-GROUNDED GUIDELINE THERAPY: Initiate clinical protocol aligned with authoritative consensus guidelines.")
                    rec_lines.append("2. DIAGNOSTIC RE-EVALUATION: Continuous hemodynamic monitoring and repeated targeted testing.")

        recs_block = "\n".join([f"  {r}" for r in rec_lines])

        # 3. Patient Safety Constraints & Withheld Therapies
        safety_lines: list[str] = []

        # Prepend critical alerts first
        if critical_alerts:
            for ca in critical_alerts:
                safety_lines.append(f"{ca}")
        elif mode == "ESCALATE_TO_HUMAN":
            safety_lines.append("🚨 CRITICAL PATHOLOGY ALERT: Emergent physician bedside evaluation required immediately.")

        if cross_modal_contradictions:
            for cmc in cross_modal_contradictions:
                prefix = "" if cmc.startswith("⚠️") else "⚠️ "
                safety_lines.append(f"{prefix}{cmc}")

        if detected_contradictions:
            for c in detected_contradictions:
                safety_lines.append(f"⚠️ {c}")
        elif mode in ["SAFETY_CONSTRAINT", "HARD_ABSTENTION"] and safety_reason:
            safety_lines.append(f"⚠️ {safety_reason}")

        if imaging_analysis and imaging_analysis.contraindicated_interventions:
            for ci in imaging_analysis.contraindicated_interventions:
                if not any(ci in sl for sl in safety_lines):
                    safety_lines.append(f"⚠️ SCAN SAFETY CONTRAINDICATION: {ci}")

        if getattr(patient, "allergies", []):
            safety_lines.append(f"⚠️ ALLERGY ALERT: Patient allergic to {', '.join(patient.allergies)}. All cross-reactive agents strictly contraindicated.")

        safety_block = "\n".join([f"  {s}" for s in safety_lines]) if safety_lines else "  • No acute pharmacological or physiological contraindications identified based on current clinical state."

        # 4. Immediate Monitoring & Diagnostic Workup
        orders = [
            f"Target Mean Arterial Pressure (MAP) >= 65 mmHg (Current SBP/DBP: {getattr(patient, 'sbp', 'N/A')}/{getattr(patient, 'dbp', 'N/A')}).",
            f"Target Oxygen Saturation SpO2: {'88-92% (COPD hypercapnic risk)' if 'copd' in chief else '>= 92%'}.",
            f"Repeat Serum Lactate and Basic Metabolic Panel (BMP for K+ and eGFR) in 2 to 4 hours.",
            f"Continuous telemetry and hourly urine output monitoring (target >= 0.5 mL/kg/h).",
        ]
        orders_block = "\n".join([f"  • {o}" for o in orders])

        # 5. Multimodal Scan Section
        scan_section = ""
        has_imaging = (vision_result is not None) or (imaging_analysis is not None) or is_fail_closed

        if has_imaging:
            if is_fail_closed:
                modality = (
                    vision_result.modality
                    if vision_result and vision_result.modality
                    else (imaging_analysis.modality if imaging_analysis and imaging_analysis.modality else "Chest X-Ray")
                )
                if vision_result is not None:
                    status_str = vision_result.status.value if hasattr(vision_result.status, "value") else str(vision_result.status)
                elif imaging_analysis is not None and imaging_analysis.metadata.get("vision_status"):
                    status_str = str(imaging_analysis.metadata["vision_status"])
                elif mode in ["ABSTAIN_INSUFFICIENT_EVIDENCE", "HARD_ABSTENTION"]:
                    status_str = "TIMEOUT" if "TIMEOUT" in (safety_reason or "") else mode
                else:
                    status_str = mode

                scan_section = (
                    f"\nVI. MULTIMODAL DIAGNOSTIC SCAN INTERPRETATION:\n"
                    f"  Modality: {modality} | Status: {status_str} (Perception Incomplete / Failed) | AI Confidence: 0.00\n"
                    f"  ⚠️ CLINICAL AUDIT NOTICE: Image analysis could not be safely or reliably completed (Status: {status_str}). Automated normal interpretation is strictly prohibited. Manual radiologist evaluation required.\n"
                    f"  Findings:\n"
                    f"  • None — Automated interpretation aborted due to technical timeout / failure.\n"
                )
            elif vision_result is not None and vision_result.status == VisionStatus.OK:
                modality = vision_result.modality or "Chest X-Ray"
                findings_bullets = []
                for f in (visual_findings or vision_result.findings):
                    ev_desc = f.evidence.heatmap_path or (str(f.evidence.bbox) if f.evidence.bbox else "Visual landmark identified")
                    findings_bullets.append(
                        f"  • {f.label}: {f.anatomical_location} (Probability: {f.probability:.2f}, Evidence: {ev_desc})"
                    )
                if not findings_bullets:
                    findings_bullets.append("  • Visual landmarks within expected limits.")

                neg_lines = ""
                if vision_result.negative_findings:
                    negs_formatted = ", ".join([f"[x] {nf.label} (Checked, Prob: {nf.probability:.2f})" for nf in vision_result.negative_findings])
                    neg_lines = f"\n  • Pertinent Negatives Evaluated: {negs_formatted}"

                confidence = max([f.probability for f in vision_result.findings], default=0.90) if vision_result.findings else 0.90
                impression = getattr(imaging_analysis, "diagnostic_impression", "")
                if not impression:
                    if visual_findings or vision_result.findings:
                        prim = (visual_findings or vision_result.findings)[0]
                        impression = f"Acute {prim.label} in {prim.anatomical_location} (Probability: {prim.probability:.2f})"
                    else:
                        impression = "No acute diagnostic abnormalities confirmed on evaluated views."

                scan_section = (
                    f"\nVI. MULTIMODAL DIAGNOSTIC SCAN INTERPRETATION:\n"
                    f"  Modality: {modality} | Status: OK | AI Confidence: {confidence:.2f}\n"
                    f"  Impression: {impression}\n"
                    f"  Radiological/Cardiographic Findings:\n" + "\n".join(findings_bullets) +
                    f"{neg_lines}\n"
                )
            elif imaging_analysis is not None:
                findings_bullets = "\n".join([f"  • {f}" for f in imaging_analysis.radiological_findings])
                scan_section = (
                    f"\nVI. MULTIMODAL DIAGNOSTIC SCAN INTERPRETATION:\n"
                    f"  Modality: {imaging_analysis.modality} | Urgency: {imaging_analysis.critical_urgency} | AI Confidence: {imaging_analysis.confidence:.2f}\n"
                    f"  Impression: {imaging_analysis.diagnostic_impression}\n"
                    f"  Radiological/Cardiographic Findings:\n{findings_bullets}\n"
                )

        report = (
            f"================================================================================\n"
            f"PATIENT-SPECIFIC CLINICAL DECISION SUPPORT REPORT (MedAgentX ACMR Engine)\n"
            f"================================================================================\n"
            f"Patient ID: {getattr(patient, 'patient_id', 'PT-001')} | Demographics: {getattr(patient, 'age', 'N/A')}yo {getattr(patient, 'sex', '')}\n"
            f"Chief Complaint: {getattr(patient, 'chief_complaint', 'Clinical Presentation')}\n"
            f"Composite Evidence Confidence (C_total): {c_total:.4f} | Status: {mode}\n\n"
            f"I. CLINICAL TRIAGE & ACUTE RISK STRATIFICATION:\n{triage_block}\n\n"
            f"II. EVIDENCE-GROUNDED CLINICAL RECOMMENDATIONS:\n{recs_block}\n\n"
            f"III. PATIENT SAFETY CONSTRAINTS & WITHHELD MEDICATIONS:\n{safety_block}\n\n"
            f"IV. IMMEDIATE MONITORING & DIAGNOSTIC WORKUP:\n{orders_block}\n"
            f"{scan_section}\n"
            f"V. RETRIEVED GUIDELINE CITATIONS:\n"
            f"{evidence_summary[:400]}...\n\n"
            f"DECISION SUPPORT DISCLAIMER:\n"
            f"  {DECISION_SUPPORT_DISCLAIMER}\n"
            f"================================================================================"
        )

        return ReasonerOutput(
            clinical_report=report,
            differential_diagnosis=triage_flags,
            citations=list(set(citations)),
            limitations=["Clinical decision support recommendation for clinician augmentation only."],
            synthesis_mode=mode,
        )

    def export_report_json(
        self,
        patient: Any,
        reasoner_output: ReasonerOutput,
        vision_result: VisionResult | None = None,
    ) -> str:
        """Export structured clinical decision support report into clean JSON."""
        patient_id = getattr(patient, "patient_id", "PT-UNKNOWN")
        report_text = reasoner_output.clinical_report

        # Triage Level
        if "🚨 CRITICAL" in report_text or "CRITICAL:" in report_text or reasoner_output.synthesis_mode == "ESCALATE_TO_HUMAN":
            triage_level = "CRITICAL"
        elif "URGENT:" in report_text or reasoner_output.synthesis_mode == "REQUEST_MORE_INPUT":
            triage_level = "URGENT"
        elif reasoner_output.synthesis_mode in ["ABSTAIN_INSUFFICIENT_EVIDENCE", "ABSTENTION", "HARD_ABSTENTION"]:
            triage_level = "ABSTAIN"
        else:
            triage_level = "ROUTINE"

        # Recommendations extraction
        recommendations: list[str] = []
        if "II. EVIDENCE-GROUNDED CLINICAL RECOMMENDATIONS:" in report_text:
            sec_ii = report_text.split("II. EVIDENCE-GROUNDED CLINICAL RECOMMENDATIONS:")[1].split("III. PATIENT SAFETY")[0]
            for line in sec_ii.strip().split("\n"):
                cleaned = line.strip()
                if cleaned:
                    recommendations.append(cleaned)

        # Contraindications extraction
        contraindications: list[str] = []
        if "III. PATIENT SAFETY CONSTRAINTS & WITHHELD MEDICATIONS:" in report_text:
            sec_iii = report_text.split("III. PATIENT SAFETY CONSTRAINTS & WITHHELD MEDICATIONS:")[1].split("IV. IMMEDIATE MONITORING")[0]
            for line in sec_iii.strip().split("\n"):
                cleaned = line.strip()
                if cleaned:
                    contraindications.append(cleaned)

        # Findings extraction
        findings_payload: list[dict[str, Any]] = []
        if vision_result and vision_result.findings:
            for f in vision_result.findings:
                findings_payload.append({
                    "finding_id": f.finding_id,
                    "label": f.label,
                    "code": f.code,
                    "anatomical_location": f.anatomical_location,
                    "laterality": f.laterality,
                    "probability": f.probability,
                    "uncertainty": f.uncertainty,
                    "is_critical": f.is_critical,
                    "evidence": f.evidence.model_dump() if hasattr(f.evidence, "model_dump") else str(f.evidence),
                })
        elif "Findings:" in report_text:
            lines = report_text.split("\n")
            in_findings = False
            for line in lines:
                if "Findings:" in line:
                    in_findings = True
                    continue
                if in_findings:
                    if line.strip().startswith("•") or line.strip().startswith("-"):
                        findings_payload.append({"finding": line.strip()})
                    elif line.strip().startswith("V. ") or line.strip().startswith("DECISION"):
                        break

        data = {
            "patient_id": patient_id,
            "triage_level": triage_level,
            "synthesis_mode": reasoner_output.synthesis_mode,
            "recommendations": recommendations,
            "contraindications": contraindications,
            "findings": findings_payload,
            "citations": reasoner_output.citations,
            "disclaimer": DECISION_SUPPORT_DISCLAIMER,
        }
        return json.dumps(data, indent=2)

    def export_report_html(
        self,
        patient: Any,
        reasoner_output: ReasonerOutput,
        vision_result: VisionResult | None = None,
    ) -> str:
        """Export styled glassmorphic HTML clinical decision support report."""
        patient_id = html.escape(str(getattr(patient, "patient_id", "PT-UNKNOWN")))
        age = html.escape(str(getattr(patient, "age", "N/A")))
        sex = html.escape(str(getattr(patient, "sex", "")))
        chief = html.escape(str(getattr(patient, "chief_complaint", "")))
        mode = html.escape(reasoner_output.synthesis_mode)

        # Status badge CSS & text
        if mode in ["ESCALATE_TO_HUMAN", "CRITICAL"]:
            badge_class = "badge-critical"
            status_label = "CRITICAL / ESCALATE"
        elif mode in ["ABSTAIN_INSUFFICIENT_EVIDENCE", "HARD_ABSTENTION"]:
            badge_class = "badge-abstain"
            status_label = f"FAIL-CLOSED: {mode}"
        elif mode == "REQUEST_MORE_INPUT":
            badge_class = "badge-warning"
            status_label = "SUBOPTIMAL: REPEAT ACQUISITION"
        else:
            badge_class = "badge-ok"
            status_label = f"DECISION STATUS: {mode}"

        # Findings HTML
        findings_html = ""
        if vision_result and vision_result.findings:
            items = []
            for f in vision_result.findings:
                ev_str = f.evidence.heatmap_path or (str(f.evidence.bbox) if f.evidence.bbox else "Visual landmark identified")
                pill = f'<span class="evidence-pill">Evidence: {html.escape(str(ev_str))}</span>'
                crit_pill = '<span class="badge badge-critical" style="margin-left:8px;">CRITICAL</span>' if f.is_critical else ""
                items.append(
                    f'<li class="finding-item">'
                    f'<strong>{html.escape(f.label)}</strong> — {html.escape(f.anatomical_location)} '
                    f'(Probability: {f.probability:.2f}) {crit_pill}'
                    f'<div style="margin-top:4px;">{pill}</div>'
                    f'</li>'
                )
            findings_html = f'<ul class="findings-list">{"".join(items)}</ul>'
        else:
            findings_html = '<p class="text-muted">No localized visual findings recorded or perception aborted.</p>'

        # Negative findings HTML
        neg_html = ""
        if vision_result and vision_result.negative_findings:
            neg_items = [
                f'<span class="badge badge-secondary" style="margin-right:6px;">[x] {html.escape(nf.label)} ({nf.probability:.2f})</span>'
                for nf in vision_result.negative_findings
            ]
            neg_html = f'<div style="margin-top:10px;"><strong>Pertinent Negatives:</strong> {"".join(neg_items)}</div>'

        escaped_report = html.escape(reasoner_output.clinical_report)

        return f"""<!DOCTYPE html>
<html lang="en">
<head>
  <meta charset="UTF-8">
  <title>MedAgentX Clinical Report - {patient_id}</title>
  <style>
    body {{
      font-family: -apple-system, BlinkMacSystemFont, "Segoe UI", Roboto, Helvetica, Arial, sans-serif;
      background: #0f172a;
      color: #f8fafc;
      padding: 30px;
      margin: 0;
    }}
    .glassmorphic-card {{
      background: rgba(30, 41, 59, 0.7);
      backdrop-filter: blur(12px);
      -webkit-backdrop-filter: blur(12px);
      border: 1px solid rgba(255, 255, 255, 0.12);
      border-radius: 16px;
      padding: 24px;
      margin-bottom: 24px;
      box-shadow: 0 8px 32px 0 rgba(0, 0, 0, 0.37);
    }}
    .header-bar {{
      display: flex;
      justify-content: space-between;
      align-items: center;
      border-bottom: 1px solid rgba(255, 255, 255, 0.1);
      padding-bottom: 16px;
      margin-bottom: 20px;
    }}
    .header-title {{
      font-size: 20px;
      font-weight: 700;
      letter-spacing: 0.5px;
      color: #38bdf8;
    }}
    .badge {{
      display: inline-block;
      padding: 6px 14px;
      border-radius: 9999px;
      font-size: 12px;
      font-weight: 600;
      text-transform: uppercase;
      letter-spacing: 0.5px;
    }}
    .badge-ok {{ background: rgba(34, 197, 94, 0.2); color: #4ade80; border: 1px solid rgba(34, 197, 94, 0.4); }}
    .badge-critical {{ background: rgba(239, 68, 68, 0.2); color: #f87171; border: 1px solid rgba(239, 68, 68, 0.4); }}
    .badge-abstain {{ background: rgba(234, 179, 8, 0.2); color: #facc15; border: 1px solid rgba(234, 179, 8, 0.4); }}
    .badge-warning {{ background: rgba(249, 115, 22, 0.2); color: #fb923c; border: 1px solid rgba(249, 115, 22, 0.4); }}
    .badge-secondary {{ background: rgba(148, 163, 184, 0.15); color: #cbd5e1; border: 1px solid rgba(148, 163, 184, 0.3); }}
    .evidence-pill {{
      display: inline-block;
      background: rgba(56, 189, 248, 0.15);
      border: 1px solid rgba(56, 189, 248, 0.3);
      color: #7dd3fc;
      padding: 4px 10px;
      border-radius: 6px;
      font-size: 12px;
      font-family: monospace;
    }}
    .findings-list {{
      list-style-type: none;
      padding: 0;
      margin: 0;
    }}
    .finding-item {{
      padding: 10px 0;
      border-bottom: 1px solid rgba(255, 255, 255, 0.06);
    }}
    .report-text {{
      white-space: pre-wrap;
      font-family: ui-monospace, SFMono-Regular, Menlo, Monaco, Consolas, monospace;
      font-size: 13px;
      line-height: 1.6;
      background: rgba(15, 23, 42, 0.6);
      padding: 16px;
      border-radius: 8px;
      border: 1px solid rgba(255, 255, 255, 0.08);
    }}
    .disclaimer-box {{
      background: rgba(239, 68, 68, 0.08);
      border: 1px solid rgba(239, 68, 68, 0.3);
      border-radius: 10px;
      padding: 14px;
      color: #fca5a5;
      font-size: 13px;
      line-height: 1.5;
    }}
    .text-muted {{ color: #94a3b8; font-style: italic; }}
  </style>
</head>
<body>
  <div class="glassmorphic-card">
    <div class="header-bar">
      <div>
        <div class="header-title">MEDAGENTX RADIOLOGY CDSS CONSULTATION</div>
        <div style="font-size:14px; color:#94a3b8; margin-top:4px;">
          Patient ID: <strong>{patient_id}</strong> | {age}yo {sex} | Chief Complaint: {chief}
        </div>
      </div>
      <div>
        <span class="badge {badge_class}">{status_label}</span>
      </div>
    </div>

    <h3>Structured Radiological Perception</h3>
    {findings_html}
    {neg_html}
  </div>

  <div class="glassmorphic-card">
    <h3>Synthesized Clinical Report</h3>
    <div class="report-text">{escaped_report}</div>
  </div>

  <div class="disclaimer-box">
    <strong>DECISION SUPPORT DISCLAIMER:</strong> {html.escape(DECISION_SUPPORT_DISCLAIMER)}
  </div>
</body>
</html>"""
